import { createHash } from 'node:crypto';

export const REQUIRED_ACCEPTANCE_IDS = Array.from({length:30},(_,i)=>`AT-${String(i+1).padStart(3,'0')}`);
export const REQUIRED_ADVERSARIAL_IDS = Array.from({length:7},(_,i)=>`ADV-${String(i+1).padStart(3,'0')}`);

function normalize(value: unknown): unknown {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'number' && !Number.isFinite(value)) throw new Error('non-finite numbers are not canonicalizable');
    return value;
  }
  if (Array.isArray(value)) return value.map(normalize);
  const out: Record<string,unknown> = {};
  for (const key of Object.keys(value as Record<string,unknown>).sort()) {
    const v=(value as Record<string,unknown>)[key];
    if (v !== undefined) out[key]=normalize(v);
  }
  return out;
}
export function canonicalize(value: unknown): string { return JSON.stringify(normalize(value)); }
export function hashCanonical(value: unknown): string { return 'sha256:'+createHash('sha256').update(canonicalize(value)).digest('hex'); }

export type GoldenEvent = {
  event_id:string; event_type:string; occurred_at:string; actor_id:string; actor_type:string;
  aggregate_id:string; aggregate_version:number; causation_event_id:string|null; correlation_id:string;
  input_refs:string[]; output_refs:string[]; source_refs:string[]; policy_refs:string[]; evidence_refs:string[];
  decision:string|null; reason_code:string|null; event_hash:string;
};
export type ChainRecord = { ordinal:number; event_id:string; event_hash:string; previous_chain_hash:string|null; chain_hash:string };
export type GoldenEvidence = { evidence_id:string; evidence_class:string; evidence_type:string; content:unknown; parent_evidence_ids:string[]; content_hash:string; created_at:string; privacy_class:string };
export type GoldenCase = {
  correlation_id:string; aggregate_id:string; final_state:string; events:GoldenEvent[]; event_chain:ChainRecord[];
  evidence:GoldenEvidence[]; versions:Record<string,unknown>; lineage_nodes:Array<{id:string;parents:string[]}>;
};

const CORR='corr_CLP001_GOLDEN_001';
const CASE='CASE-CLP-001-GOLDEN-001';
const T0=Date.parse('2026-10-03T22:00:00.000Z');
const POLICY='CLP-001-TRANSITIONS@1.0.0';
const MN='AUTH-MN-504B161@1.0.0';
const AV='AUTH-APPLEVALLEY-PLUMBING@CLP-FIXTURE-1';
const HUD='AUTH-HUD-NSPIRE-TOILET@CLP-FIXTURE-1';
const WORKER='WORKER-A@CLP-FIXTURE-1';
const TASK='TASKPACK-CLP-001@1.0.0';
const VERIFY='VERIFY-CLP-001@1.0.0';

function evidence(id:string, cls:string, type:string, content:unknown, parents:string[]=[], privacy='INTERNAL'):GoldenEvidence {
  const payload={evidence_id:id,evidence_class:cls,evidence_type:type,content,parent_evidence_ids:parents};
  return {...payload,content_hash:hashCanonical(payload),created_at:'2026-10-03T22:00:00.000Z',privacy_class:privacy};
}
function eventBase(i:number,type:string,actor_id:string,actor_type:string, evidence_refs:string[]=[], source_refs:string[]=[], policy_refs:string[]=[POLICY], decision:string|null=null, reason_code:string|null=null):GoldenEvent {
  const payload:any={
    event_id:`evt_CLP001_${String(i).padStart(3,'0')}`,event_type:type,occurred_at:new Date(T0+i*60000).toISOString(),actor_id,actor_type,
    aggregate_id:CASE,aggregate_version:i,causation_event_id:i===1?null:`evt_CLP001_${String(i-1).padStart(3,'0')}`,correlation_id:CORR,
    input_refs:[],output_refs:[],source_refs,policy_refs,evidence_refs,decision,reason_code
  };
  return {...payload,event_hash:hashCanonical(payload)};
}
function chainEvents(events:GoldenEvent[]):ChainRecord[] {
  let previous:string|null=null;
  return events.map((e,idx)=>{
    const record={ordinal:idx+1,event_id:e.event_id,event_hash:e.event_hash,previous_chain_hash:previous};
    const chain_hash=hashCanonical({...record,correlation_id:e.correlation_id});
    previous=chain_hash;
    return {...record,chain_hash};
  });
}

export function buildGoldenCase():GoldenCase {
  const ev0=evidence('ev_RESIDENT_STATEMENT','E0','RESIDENT_STATEMENT',{text:'The toilet keeps running and water continues filling after it should stop.'},[],'RESIDENT_PRIVATE');
  const ev1=evidence('ev_RESIDENT_PHOTO','E0','RESIDENT_PHOTO',{fixture:'toilet-tank',synthetic:true},[],'RESIDENT_PRIVATE');
  const ev2=evidence('ev_STRUCTURED_INTAKE','E1','STRUCTURED_INTAKE',{issue_class:'TOILET_FILL_VALVE_FAILURE'},[ev0.evidence_id,ev1.evidence_id]);
  const ev3=evidence('ev_AUTH_MN','E2','AUTHORITY_SOURCE',{ref:MN,status:'APPLICABLE'});
  const ev4=evidence('ev_AUTH_AV','E2','AUTHORITY_SOURCE',{ref:AV,status:'APPLICABLE'});
  const ev5=evidence('ev_AUTH_HUD','E2','AUTHORITY_SOURCE',{ref:HUD,status:'POTENTIALLY_APPLICABLE'});
  const ev6=evidence('ev_ELIGIBILITY','E3','ELIGIBILITY_DECISION',{worker:'WORKER-A',decision:'ELIGIBLE'});
  const ev7=evidence('ev_TASKPACK','E4','TASK_PACK',{ref:TASK,status:'APPROVED_ACTIVE'});
  const ev8=evidence('ev_BEFORE','E5','BEFORE_CONDITION',{continuous_running:true});
  const ev9=evidence('ev_DIAGNOSIS','E5','DIAGNOSIS',{confirmed:'fill_valve_failure',stop_condition:null},[ev8.evidence_id]);
  const ev10=evidence('ev_REPAIR','E5','REPAIR_ACTION',{action:'replace_fill_valve',scope:'approved'},[ev9.evidence_id]);
  const ev11=evidence('ev_AFTER','E5','AFTER_CONDITION',{continuous_running:false,visible_leak:false},[ev10.evidence_id]);
  const ev12=evidence('ev_VERIFY','E6','SUPERVISOR_VERIFICATION',{checks:[true,true,true,true,true,true,true,true],result:'VERIFIED'},[ev11.evidence_id]);
  const ev13=evidence('ev_WORKGRAPH','E7','WORKGRAPH_RECEIPT',{worker:'WORKER-A',claim:'VERIFIED_TASK:TOILET_FILL_VALVE_FAILURE'},[ev6.evidence_id,ev7.evidence_id,ev12.evidence_id],'PORTABLE_WORKGRAPH');
  const evidenceList=[ev0,ev1,ev2,ev3,ev4,ev5,ev6,ev7,ev8,ev9,ev10,ev11,ev12,ev13];

  const defs:Array<[string,string,string,string[],string[],string[],string|null,string|null]> = [
    ['ResidentIssueReported','RESIDENT-CLP-001','RESIDENT',[ev0.evidence_id,ev1.evidence_id],[],[],null,null],
    ['ResidentEvidenceAttached','RESIDENT-CLP-001','RESIDENT',[ev1.evidence_id],[],[],null,null],
    ['IssueIntakeStructured','SYSTEM','AI',[ev2.evidence_id],[],[], 'INTAKE_STRUCTURED',null],
    ['AuthorityRetrieved','SYSTEM','SYSTEM',[ev3.evidence_id,ev4.evidence_id,ev5.evidence_id],[MN,AV,HUD],[],null,null],
    ['AuthorityApplicabilityResolved','SYSTEM','SYSTEM',[ev3.evidence_id,ev4.evidence_id,ev5.evidence_id],[MN,AV,HUD],[], 'AUTHORITY_RESOLVED',null],
    ['RightsAnswerGenerated','SYSTEM','AI',[ev3.evidence_id,ev4.evidence_id,ev5.evidence_id],[MN,AV,HUD],[], 'RIGHTS_RESPONSE_READY',null],
    ['WorkOrderCreated','SYSTEM','SYSTEM',[ev0.evidence_id,ev2.evidence_id],[MN,AV],[], 'WORK_ORDER_CREATED',null],
    ['WorkerEligibilityEvaluated','SYSTEM','SYSTEM',[ev6.evidence_id],[],[WORKER],null,null],
    ['WorkerEligible','SYSTEM','SYSTEM',[ev6.evidence_id],[],[WORKER], 'WORKER_ELIGIBLE',null],
    ['TaskPackGenerated','SYSTEM','SYSTEM',[ev7.evidence_id],[MN,AV],[TASK],null,null],
    ['TaskPackApproved','SUPERVISOR-CLP-001','SUPERVISOR',[ev7.evidence_id],[MN,AV],[TASK], 'TASK_PACK_APPROVED',null],
    ['WorkAssigned','SYSTEM','SYSTEM',[ev6.evidence_id,ev7.evidence_id],[],[WORKER,TASK], 'ASSIGNED',null],
    ['WorkAccepted','WORKER-A','WORKER',[ev6.evidence_id,ev7.evidence_id],[],[WORKER,TASK],null,null],
    ['WorkStarted','WORKER-A','WORKER',[ev8.evidence_id],[],[WORKER,TASK], 'IN_PROGRESS',null],
    ['DiagnosticEvidenceCaptured','WORKER-A','WORKER',[ev9.evidence_id],[],[TASK],null,null],
    ['RepairActionRecorded','WORKER-A','WORKER',[ev10.evidence_id],[],[TASK],null,null],
    ['CompletionEvidenceSubmitted','WORKER-A','WORKER',[ev11.evidence_id],[],[TASK], 'AWAITING_VERIFICATION',null],
    ['VerificationPerformed','SUPERVISOR-CLP-001','SUPERVISOR',[ev12.evidence_id],[],[VERIFY,TASK],null,null],
    ['RepairVerified','SUPERVISOR-CLP-001','SUPERVISOR',[ev12.evidence_id],[],[VERIFY,TASK], 'VERIFIED',null],
    ['WorkArtifactGenerated','SYSTEM','SYSTEM',[ev13.evidence_id],[],[TASK,VERIFY],null,null],
    ['WorkGraphUpdated','SYSTEM','SYSTEM',[ev13.evidence_id],[],[TASK,VERIFY], 'WORKGRAPH_RECORDED',null],
    ['CaseClosed','SYSTEM','SYSTEM',[ev13.evidence_id],[],[POLICY], 'CLOSED',null]
  ];
  const events=defs.map((d,idx)=>eventBase(idx+1,d[0],d[1],d[2],d[3],d[4],d[5]??[POLICY],d[6]??null,d[7]??null));
  const versions:Record<string,unknown>={
    [MN]:{source_id:'AUTH-MN-504B161',version:'1.0.0',jurisdiction:'US-MN',content_hash:ev3.content_hash},
    [AV]:{source_id:'AUTH-APPLEVALLEY-PLUMBING',version:'CLP-FIXTURE-1',jurisdiction:'US-MN-DAKOTA-APPLE-VALLEY',content_hash:ev4.content_hash,production_authority_status:'PLACEHOLDER_REQUIRES_OFFICIAL_PINNING'},
    [HUD]:{source_id:'AUTH-HUD-NSPIRE-TOILET',version:'CLP-FIXTURE-1',applicability:'POTENTIALLY_APPLICABLE',content_hash:ev5.content_hash},
    [POLICY]:{policy_id:'CLP-001-TRANSITIONS',version:'1.0.0'},
    [WORKER]:{worker_id:'WORKER-A',snapshot:'CLP-FIXTURE-1',decision:'ELIGIBLE',content_hash:ev6.content_hash},
    [TASK]:{task_pack_id:'TASKPACK-CLP-001',version:'1.0.0',content_hash:ev7.content_hash},
    [VERIFY]:{verification_contract_id:'VERIFY-CLP-001',version:'1.0.0'}
  };
  const lineage_nodes:Array<{id:string;parents:string[]}>=[
    ...evidenceList.map(e=>({id:e.evidence_id,parents:e.parent_evidence_ids})),
    {id:'APPLICABILITY-CLP-001',parents:[ev3.evidence_id,ev4.evidence_id,ev5.evidence_id]},
    {id:'RIGHTS-ANSWER-CLP-001',parents:['APPLICABILITY-CLP-001']},
    {id:'WO-CLP-001',parents:[ev0.evidence_id,'RIGHTS-ANSWER-CLP-001']},
    {id:'ELIGIBILITY-CLP-001',parents:['WO-CLP-001',ev6.evidence_id]},
    {id:'TASKPACK-CLP-001',parents:['ELIGIBILITY-CLP-001',ev7.evidence_id]},
    {id:'EXECUTION-CLP-001',parents:['TASKPACK-CLP-001',ev8.evidence_id,ev9.evidence_id,ev10.evidence_id,ev11.evidence_id]},
    {id:'VERIFICATION-CLP-001',parents:['EXECUTION-CLP-001',ev12.evidence_id]},
    {id:'WORKGRAPH-CLP-001',parents:['VERIFICATION-CLP-001',ev13.evidence_id]}
  ];
  return {correlation_id:CORR,aggregate_id:CASE,final_state:'CLOSED',events,event_chain:chainEvents(events),evidence:evidenceList,versions,lineage_nodes};
}

export function verifyEventChain(events:GoldenEvent[], chain:ChainRecord[]) {
  const errors:string[]=[];
  if (events.length!==chain.length) errors.push('length mismatch');
  let prior:string|null=null;
  for(let i=0;i<Math.min(events.length,chain.length);i++){
    const e=events[i], c=chain[i];
    const payload:any={...e}; delete payload.event_hash;
    const self=hashCanonical(payload);
    if(self!==e.event_hash) errors.push(`event self-hash mismatch:${e.event_id}`);
    if(c.ordinal!==i+1||c.event_id!==e.event_id||c.event_hash!==e.event_hash||c.previous_chain_hash!==prior) errors.push(`chain order mismatch:${e.event_id}`);
    const expected=hashCanonical({ordinal:c.ordinal,event_id:c.event_id,event_hash:c.event_hash,previous_chain_hash:c.previous_chain_hash,correlation_id:e.correlation_id});
    if(expected!==c.chain_hash) errors.push(`chain hash mismatch:${e.event_id}`);
    prior=c.chain_hash;
  }
  return {valid:errors.length===0,errors,root_hash:chain.at(-1)?.chain_hash??null};
}

function validateLineage(nodes:Array<{id:string;parents:string[]}>) {
  const ids=new Set(nodes.map(n=>n.id)); const missing:string[]=[];
  for(const n of nodes) for(const p of n.parents) if(!ids.has(p)) missing.push(`${n.id}->${p}`);
  return {valid:missing.length===0,missing};
}

export class InMemoryGovernanceRepository {
  private events:GoldenEvent[]=[]; private evidence:GoldenEvidence[]=[]; private versions:Record<string,unknown>={}; private chain:ChainRecord[]=[]; private lineage:Array<{id:string;parents:string[]}>=[];
  persistGoldenCase(g:GoldenCase){ if(this.events.length||this.evidence.length||Object.keys(this.versions).length) throw new Error('repository is append-only and already initialized'); this.events=[...g.events]; this.evidence=[...g.evidence]; this.versions={...g.versions}; this.chain=[...g.event_chain]; this.lineage=g.lineage_nodes.map(x=>({...x,parents:[...x.parents]})); }
  getEvents(correlationId:string){ return this.events.filter(e=>e.correlation_id===correlationId).map(e=>({...e})); }
  getEvidence(){ return this.evidence.map(e=>({...e,parent_evidence_ids:[...e.parent_evidence_ids]})); }
  getVersions(){ return {...this.versions}; }
  getChain(correlationId:string){ const ids=new Set(this.getEvents(correlationId).map(e=>e.event_id)); return this.chain.filter(c=>ids.has(c.event_id)).map(c=>({...c})); }
  getLineage(){ return this.lineage.map(x=>({...x,parents:[...x.parents]})); }
  deleteEvent():never{ throw new Error('append-only repository: destructive deletion prohibited'); }
  deleteEvidence():never{ throw new Error('append-only repository: destructive deletion prohibited'); }
}

export function replayGoldenCase(correlationId:string, repo:InMemoryGovernanceRepository){
  const events=repo.getEvents(correlationId); if(!events.length) throw new Error('correlation id not found');
  for(let i=0;i<events.length;i++){
    if(events[i].aggregate_version!==i+1) throw new Error('non-monotonic aggregate version');
    if(i===0&&events[i].causation_event_id!==null) throw new Error('first event causation must be null');
    if(i>0&&events[i].causation_event_id!==events[i-1].event_id) throw new Error('causation chain broken');
  }
  const chainCheck=verifyEventChain(events,repo.getChain(correlationId)); if(!chainCheck.valid) throw new Error('event chain invalid');
  const evidence=repo.getEvidence(); const evidenceIds=new Set(evidence.map(e=>e.evidence_id));
  const refs=new Set<string>(); for(const e of events){ for(const x of e.evidence_refs) if(!evidenceIds.has(x)) throw new Error(`missing evidence ${x}`); for(const x of [...e.source_refs,...e.policy_refs]) refs.add(x); }
  const versions=repo.getVersions(); const resolved_versions:Record<string,unknown>={}; for(const r of refs){ if(!(r in versions)) throw new Error(`missing pinned version ${r}`); resolved_versions[r]=versions[r]; }
  const lineage=validateLineage(repo.getLineage()); if(!lineage.valid) throw new Error('lineage invalid');
  const result={correlation_id:correlationId,final_state:events.at(-1)?.decision==='CLOSED'?'CLOSED':'UNKNOWN',events,evidence,resolved_versions,event_chain_root:chainCheck.root_hash,lineage_nodes:repo.getLineage()};
  return {...result,replay_hash:hashCanonical(result)};
}

function exactPassing(required:string[], actual:Array<{id:string;status:string}>){ const map=new Map(actual.map(x=>[x.id,x.status])); return required.every(id=>map.get(id)==='PASS') && actual.every(x=>required.includes(x.id)); }
export function issueCertification(g:GoldenCase, input:{acceptance:Array<{id:string;status:string}>;adversarial:Array<{id:string;status:string}>;implementation_commit:string|null}){
  const chain=verifyEventChain(g.events,g.event_chain); const lineage=validateLineage(g.lineage_nodes);
  if(!chain.valid||!lineage.valid||g.final_state!=='CLOSED'||!exactPassing(REQUIRED_ACCEPTANCE_IDS,input.acceptance)||!exactPassing(REQUIRED_ADVERSARIAL_IDS,input.adversarial)) throw new Error('certification refused: frozen gates not satisfied');
  const repo=new InMemoryGovernanceRepository(); repo.persistGoldenCase(g); const replay=replayGoldenCase(g.correlation_id,repo);
  const authority_fixture_hashes=[MN,AV,HUD].map(ref=>({ref,hash:hashCanonical(g.versions[ref])}));
  const policy_fixture_hashes=[POLICY,WORKER,VERIFY].map(ref=>({ref,hash:hashCanonical(g.versions[ref])}));
  const task_pack_hash=hashCanonical(g.versions[TASK]);
  const cert:any={
    certification_id:'CLP001Certification',spec_version:'1.0.0',kap_version:'1.0.0',implementation_commit:input.implementation_commit,
    implementation_commit_binding_status:input.implementation_commit?'BOUND':'PENDING_TARGET_REPOSITORY_COMMIT',test_suite_version:'CLP-001-C-1.0.0',
    authority_fixture_hashes,policy_fixture_hashes,task_pack_hash,event_count:g.events.length,evidence_count:g.evidence.length,
    acceptance_results:input.acceptance,adversarial_results:input.adversarial,replay_hash:replay.replay_hash,event_chain_root:chain.root_hash,
    certified_at:'2026-10-03T23:00:00.000Z',certified_by:'BUILD-CLP-001-C',
    certification_status:input.implementation_commit?'CERTIFIED':'CERTIFIED_WITH_PENDING_COMMIT_BINDING'
  };
  cert.certification_hash=hashCanonical(cert); return cert;
}
